import { useState, useEffect, useRef } from 'react'
import useAppStore from '../store/appStore'

export default function HShape() {
  const [shapes,   setShapes]   = useState([])
  const [query,    setQuery]    = useState('')
  const [selected, setSelected] = useState(null)
  const [error,    setError]    = useState(null)
  const canvasRef = useRef(null)

  const { setActiveView, setPendingWShape, pendingHShape, clearPendingHShape } = useAppStore()
  const dataBase = window.location.pathname.replace(/\/$/, '') + '/'

  useEffect(() => {
    fetch(`${dataBase}data/hShapes.json`)
      .then(r => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json() })
      .then(data => setShapes([...data].sort((a, b) => a.H - b.H || a.w - b.w)))
      .catch(e => setError(`H-Shape data load failed: ${e.message}`))
  }, [])

  // Auto-select shape when navigated from W-Shape cross-reference
  useEffect(() => {
    if (shapes.length && pendingHShape) {
      const match = shapes.find(s => s.name === pendingHShape.name)
      if (match) setSelected(match)
      clearPendingHShape()
    }
  }, [shapes, pendingHShape])

  useEffect(() => {
    if (selected && canvasRef.current) drawHShape(canvasRef.current, selected)
  }, [selected])

  // Group by H (depth) series
  const groups = {}
  const filtered = query.length >= 2
    ? shapes.filter(s => s.name.toLowerCase().includes(query.toLowerCase()))
    : shapes
  filtered.forEach(s => {
    const key = `H-${s.H}`
    if (!groups[key]) groups[key] = []
    groups[key].push(s)
  })

  // Find similar Sx cross-references from W-shapes
  const [wShapes, setWShapes] = useState([])
  useEffect(() => {
    fetch(`${dataBase}data/wShapes.json`).then(r => r.json()).then(setWShapes).catch(() => {})
  }, [])

  const similarW = selected ? findSimilarW(selected, wShapes) : []

  function gotoWShape(w) {
    setPendingWShape(w)
    setActiveView('steel-w')
  }

  return (
    <div>
      <h3 style={titleStyle}>H-SHAPE (KS D 3502)</h3>
      <input placeholder="Search (e.g. H-300, 300×150)"
        value={query} onChange={e => setQuery(e.target.value)}
        style={{ ...inputStyle, marginBottom: 16, width: 280 }} />

      <div style={{ display: 'flex', gap: 16, alignItems: 'flex-start' }}>
        {/* Left: series list */}
        <div style={{ width: 220, flexShrink: 0, overflowY: 'auto', maxHeight: 600 }}>
          {Object.entries(groups).map(([series, items]) => (
            <div key={series} style={{ marginBottom: 6 }}>
              <div style={seriesHead}>{series} series</div>
              {items.map(s => (
                <button key={s.name} onClick={() => setSelected(s)} style={{
                  display: 'block', width: '100%', textAlign: 'left',
                  padding: '5px 10px', borderRadius: 4, fontSize: 11,
                  cursor: 'pointer', border: 'none', marginBottom: 2,
                  background: selected?.name === s.name ? 'var(--ac-main)' : 'var(--bg-card)',
                  color: selected?.name === s.name ? '#000' : 'var(--tx-secondary)',
                  borderLeft: `3px solid ${selected?.name === s.name ? '#000' : 'transparent'}`,
                }}>
                  <span style={{ fontWeight: 600 }}>{s.name}</span>
                  <span style={{ marginLeft: 6, opacity: 0.7, fontSize: 10 }}>{s.w} kg/m</span>
                </button>
              ))}
            </div>
          ))}
        </div>

        {/* Right: properties + cross-ref */}
        {selected ? (
          <div style={{ flex: 1 }}>
            <div className="grid md:grid-cols-2 gap-6">
              <div>
                <canvas ref={canvasRef} width={280} height={230}
                  style={{ background: 'var(--bg-inset)', borderRadius: 8, display: 'block', marginBottom: 8 }} />
                <p style={{ fontSize: 10, color: 'var(--tx-muted)' }}>Cross-section (proportional)</p>
              </div>
              <div>
                <h4 style={{ fontSize: 14, fontWeight: 700, color: 'var(--ac-main)', marginBottom: 4 }}>
                  {selected.name}
                  <span style={{ fontSize: 11, color: 'var(--tx-muted)', marginLeft: 8 }}>{selected.w} kg/m</span>
                </h4>
                <SectionHeader>Section Dimensions</SectionHeader>
                <PropTable data={[
                  ['H (height)', `${selected.H} mm`], ['B (flange width)', `${selected.B} mm`],
                  ['tw (web)', `${selected.tw} mm`],  ['tf (flange)', `${selected.tf} mm`],
                  ['r (fillet)', `${selected.r} mm`],
                ]} />
                <SectionHeader>Section Properties</SectionHeader>
                <PropTable data={[
                  ['A', `${selected.A} cm²`],    ['Ix', `${selected.Ix} cm⁴`],
                  ['Sx', `${selected.Sx} cm³`],  ['rx', `${selected.rx} cm`],
                  ['Iy', `${selected.Iy} cm⁴`],  ['Sy', `${selected.Sy} cm³`],
                  ['ry', `${selected.ry} cm`],   ['W',  `${selected.w} kg/m`],
                ]} />
              </div>
            </div>

            {/* Cross-reference: similar W-shapes by Sx */}
            {similarW.length > 0 && (
              <div style={{ marginTop: 16 }}>
                <SectionHeader>Similar AISC W-Shapes (Sx ≈ {selected.Sx} cm³ ± 20%)</SectionHeader>
                <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                  {similarW.map(w => (
                    <button key={w.label_in} onClick={() => gotoWShape(w)} style={{
                      padding: '4px 10px', borderRadius: 5,
                      fontSize: 11, cursor: 'pointer',
                      background: 'var(--bg-card)', border: '1px solid var(--bd-accent)',
                      color: 'var(--ac-main)',
                    }}>
                      {w.label_in}
                      <span style={{ fontSize: 10, color: 'var(--tx-muted)', marginLeft: 4 }}>
                        Sx={(w.Sx * 16.387).toFixed(0)} cm³
                      </span>
                    </button>
                  ))}
                </div>
                <p style={{ fontSize: 10, color: 'var(--tx-muted)', marginTop: 6 }}>
                  Click to navigate to W-Shape view
                </p>
              </div>
            )}
          </div>
        ) : (
          <div style={{ flex: 1, ...hint }}>← Select a shape from the list to view section properties</div>
        )}
      </div>

      {error && <p style={{ color: 'var(--val-warn)', fontSize: 13, marginTop: 12 }}>⚠ {error}</p>}
    </div>
  )
}

function findSimilarW(hShape, wShapes) {
  if (!wShapes?.length) return []
  const Sx_cm3 = hShape.Sx
  return wShapes
    .filter(w => {
      const wSx = w.Sx * 16.387  // in³ → cm³
      return Math.abs(wSx - Sx_cm3) / Sx_cm3 <= 0.20
    })
    .sort((a, b) => Math.abs(a.Sx * 16.387 - Sx_cm3) - Math.abs(b.Sx * 16.387 - Sx_cm3))
    .slice(0, 8)
}

function SectionHeader({ children }) {
  return <div style={{ fontSize: 10, fontWeight: 700, color: 'var(--ac-main)', letterSpacing: '0.07em', textTransform: 'uppercase', marginTop: 12, marginBottom: 5, paddingBottom: 3, borderBottom: '1px solid var(--bd-subtle)' }}>{children}</div>
}
function PropTable({ data }) {
  return (
    <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12, marginBottom: 2 }}>
      <tbody>{data.map(([l, v]) => (
        <tr key={l}>
          <td style={ptd1}>{l}</td>
          <td style={ptd2}>{v}</td>
        </tr>
      ))}</tbody>
    </table>
  )
}
function drawHShape(canvas, s) {
  const ctx = canvas.getContext('2d')
  ctx.clearRect(0, 0, canvas.width, canvas.height)
  const W = canvas.width, H = canvas.height
  const scale = Math.min((W - 60) / s.B, (H - 50) / s.H) * 0.85
  const x0 = (W - s.B * scale) / 2, y0 = (H - s.H * scale) / 2
  ctx.fillStyle = 'rgba(38,198,218,0.15)'; ctx.strokeStyle = '#26c6da'; ctx.lineWidth = 1.5
  const bS = s.B * scale, hS = s.H * scale, twS = s.tw * scale, tfS = s.tf * scale
  ctx.fillRect(x0, y0, bS, tfS); ctx.strokeRect(x0, y0, bS, tfS)
  ctx.fillRect(x0, y0 + hS - tfS, bS, tfS); ctx.strokeRect(x0, y0 + hS - tfS, bS, tfS)
  const wx = x0 + (bS - twS) / 2
  ctx.fillRect(wx, y0 + tfS, twS, hS - 2 * tfS); ctx.strokeRect(wx, y0 + tfS, twS, hS - 2 * tfS)
  ctx.strokeStyle = '#90caf960'; ctx.lineWidth = 0.8; ctx.setLineDash([3, 3])
  ctx.beginPath(); ctx.moveTo(x0 - 10, y0); ctx.lineTo(x0 - 10, y0 + hS); ctx.stroke()
  ctx.beginPath(); ctx.moveTo(x0, y0 - 10); ctx.lineTo(x0 + bS, y0 - 10); ctx.stroke()
  ctx.setLineDash([])
  ctx.fillStyle = '#90caf9'; ctx.font = '9px Inter,Arial'
  ctx.fillText(`H=${s.H}`, x0 - 42, y0 + hS / 2)
  ctx.fillText(`B=${s.B}`, x0 + bS / 2 - 14, y0 - 13)
}

const titleStyle = { fontSize: '1.3rem', fontWeight: 700, marginBottom: 20, color: 'var(--tx-primary)', paddingBottom: 10, borderBottom: '1px solid var(--bd-subtle)' }
const inputStyle = { background: 'var(--bg-input)', border: '1px solid var(--bd-subtle)', borderRadius: 6, color: 'var(--tx-primary)', padding: '6px 10px', fontSize: 13 }
const hint       = { padding: '12px 16px', borderRadius: 8, background: 'var(--bg-inset)', border: '1px dashed var(--bd-subtle)', color: 'var(--tx-muted)', fontSize: 13, alignSelf: 'flex-start' }
const seriesHead = { fontSize: 10, fontWeight: 700, color: 'var(--ac-main)', letterSpacing: '0.05em', textTransform: 'uppercase', padding: '4px 8px', background: 'var(--bg-inset)', borderRadius: 4, marginBottom: 3 }
const ptd1 = { padding: '3px 6px', color: 'var(--tx-secondary)', borderBottom: '1px solid var(--bd-subtle)', width: '50%', fontSize: 12 }
const ptd2 = { padding: '3px 6px', fontWeight: 700, color: 'var(--val-pos)', borderBottom: '1px solid var(--bd-subtle)', fontSize: 12 }
